/// The part a participant played in a run.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Role {
    /// The machine where the command was typed.
    Initiator,
    /// A daemon serving the files being sent.
    Source,
    /// A daemon receiving them.
    Destination,
}

impl Role {
    pub fn as_str(self) -> &'static str {
        match self {
            Role::Initiator => "initiator",
            Role::Source => "source",
            Role::Destination => "destination",
        }
    }

    fn parse(text: &str) -> Option<Self> {
        [Role::Initiator, Role::Source, Role::Destination]
            .into_iter()
            .find(|role| role.as_str() == text)
    }
}

impl std::str::FromStr for Role {
    type Err = eyre::Report;

    fn from_str(text: &str) -> eyre::Result<Self> {
        Self::parse(text).ok_or_else(|| {
            eyre::eyre!("unknown role {text:?}: expected initiator, source or destination")
        })
    }
}

/// Whether `id` can be a run or participant ID in a [`LogKey`].
pub fn valid_id(id: &str) -> bool {
    check_id("ID", id).is_ok()
}

/// Which log: run ID + participant + role + attempt.
///
/// The parts become the log's file name, so the two IDs are limited to 1–64
/// lowercase ASCII letters, digits, `-` and `_` — nothing that could leave
/// the log folder, and no two keys a case-insensitive file system would take
/// for one.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
/// the daemon named first, or on this machine — or the one log file named,
/// as text or, with `--json`, as its JSON lines.
async fn run_jobs_log(args: JobsLogArgs) -> Result<()> {
    let role = args.role.map(|role| match role {
        LogRole::Initiator => Role::Initiator,
        LogRole::Source => Role::Source,
        LogRole::Destination => Role::Destination,
    });
    let json = args.json;
    let Some(job_id) = args.job_id else {
        let target = args.target;
        let went_on = detached_ending(&target).await;
        let shown = {
            let target = target.clone();
            tokio::task::spawn_blocking(move || {
                let stdout = std::io::stdout();
                let mut out = stdout.lock();
                write_local_log(&mut out, &target, role, json)
            })
            .await
            .context("reading the log")?
        };
        if let Some(went_on) = went_on {
            eprintln!("blit: {went_on}");
        }
        return shown;
    };
    let remote = RemoteEndpoint::parse(&args.target)
        .with_context(|| format!("parsing remote endpoint '{}'", args.target))?;
    let mut first = true;
    jobs::read_job_logs(&remote, &job_id, role, false, move |header, lines| {
        let stdout = std::io::stdout();
        let mut out = stdout.lock();
        if json {
            write_json_log(&mut out, lines)?;
        } else {
            if !first {
                writeln!(out)?;
            }
            write_text_log(&mut out, &Heading::from_daemon(&header), lines)?;
        }
        first = false;
        out.flush()?;
        Ok(())
    })
    .await
}

/// For a job run here that went on on a daemon (`--detach`): how it ended
/// there, once the daemon is asked (its record is updated), or why that is
/// not known yet. `None` for any other job, or a file.
async fn detached_ending(target: &str) -> Option<String> {
    if job_record::names_a_path(target) || !job_log::valid_id(target) {
        return None;
    }
    let store = RunStore::new(crate::run_log::runs_dir(
        &blit_core::config::config_dir().ok()?,
    ));
    let loaded = {
        let (store, run_id) = (store.clone(), target.to_string());
        tokio::task::spawn_blocking(move || store.load(&run_id))
            .await
            .ok()?
            .ok()?
    };
    let RunState::Waiting { daemon, job_id } = loaded.1.state.clone() else {
        return None;
    };
    let (record, note) = settle_detached(&store, loaded.1).await;
    let there = format!("`blit jobs log {daemon} {job_id}` shows its log there");
    Some(match (note, record.outcome) {
        (Some(note), _) => format!("job {target} went on on {daemon} as job {job_id}: {note}"),
        (None, Some(outcome)) => {
            let detail = record
                .detail
                .map(|detail| format!(": {detail}"))
                .unwrap_or_default();
            format!(
                "job {target} went on on {daemon} as job {job_id} and ended {}{detail}; {there}",
                outcome.as_str()
            )
        }
        (None, None) => format!("job {target} went on on {daemon} as job {job_id}; {there}"),
    })
}

/// What `blit jobs log` prints above a log's text.
struct Heading {
    role: String,
    participant: String,
    attempt: u32,
    /// Why the log may not be finished, when it is not.
    unfinished: Option<&'static str>,
}

impl Heading {
    fn from_daemon(header: &JobLogHeader) -> Self {
        Self {
            role: header.role.clone(),
            participant: header.participant.clone(),
            attempt: header.attempt,
            unfinished: (!header.finished)
                .then_some("the job is running, or the daemon stopped during it"),
        }
    }

    fn from_disk(role: Role, participant: &str, attempt: u32, finished: bool) -> Self {
        Self {
            role: role.as_str().to_string(),
            participant: participant.to_string(),
            attempt,
            unfinished: (!finished).then_some("the job is running"),
        }
    }
}

/// `blit jobs log <job-id|file>` (jl-2): a job run on this machine — every
/// log kept for it here — or the one log file named. A name that is a file
/// is read as one; any other is a job ID.
fn write_local_log(
    out: &mut impl Write,
    target: &str,
    role: Option<Role>,
    json: bool,
) -> Result<()> {
    let file = Path::new(target);
    // Review cr-jl3b-1: a path is a file, a bare word a job ID.
    let logs: Vec<(PathBuf, Heading)> = if job_record::names_a_path(target) {
        if role.is_some() {
            eyre::bail!("--role picks among a job's logs; {target} is one log file");
        }
        if json {
            // Any file's lines as stored, a damaged log's too.
            write_json_log(out, open_stored(file)?)?;
            out.flush()?;
            return Ok(());
        }
        let start =
            job_log::read_start(file).with_context(|| format!("reading {}", file.display()))?;
        let heading = Heading::from_disk(
            start.role,
            &start.participant,
            start.attempt,
            !job_log::is_partial(file),
        );
        vec![(file.to_path_buf(), heading)]
    } else if job_log::valid_id(target) {
        let dir = crate::run_log::logs_dir(&blit_core::config::config_dir()?);
        let found = job_log::logs_for_run(&dir, target, role)?;
        if found.is_empty() {
            eyre::bail!(
                "no log for job {target} on this machine (`blit jobs list` shows the \
                 jobs kept here; for a daemon's job, name its host first: \
                 `blit jobs log <host> <job-id>`)"
            );
        }
        found
            .into_iter()
            .map(|log| {
                let heading = Heading::from_disk(
                    log.key.role(),
                    log.key.participant(),
                    log.key.attempt(),
                    log.finished,
                );
                (log.path, heading)
            })
            .collect()
    } else {
        eyre::bail!("{target} is not a log file or a job ID");
    };
    for (index, (path, heading)) in logs.iter().enumerate() {
        let lines = open_stored(path)?;
        if json {
            write_json_log(out, lines)?;
        } else {
                run_diagnostics_perf(&mut ctx, &args)?;
                ExitCode::SUCCESS
            }
            DiagnosticsCommand::Dump(args) => {
                run_diagnostics_dump(&args)?;
                ExitCode::SUCCESS
            }
        },
        // `jobs cancel` exits 0/1/2 (Cancelled / NotFound /
        // Unsupported) per the §6.5 contract; `jobs list`
        // always exits 0. The runner returns the right
        // `ExitCode` for both; propagate it directly like
        // `check`.
        // JOB_LOGS jl-3b: a saved job runs as the command it was.
        Commands::Jobs {
            command: JobsCommand::Run(args),
        } => {
            let job = jobs::job_to_run(&args.job).await?;
            let verb = Verb::from_word(&job.verb)
                .ok_or_else(|| eyre::eyre!("a job of an unknown kind ({})", job.verb))?;
            let jobs::JobToRun {
                args, saved, _list, ..
            } = job;
            Box::pin(run_command(&ctx, verb, args, lifecycle_trace, saved)).await?
        }
        Commands::Jobs { command } => run_jobs(command).await?,
    };

    Ok(exit_code)
}

/// The transfer verbs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Verb {
    Copy,
    Mirror,
        command: DiagnosticsCommand,
    },
    /// Inspect transfer jobs and their logs, on this machine or a daemon
    Jobs {
        #[command(subcommand)]
        command: JobsCommand,
    },
}

#[derive(Subcommand)]
pub enum JobsCommand {
    /// List the jobs run on this machine, or a daemon's active and recent
    /// transfers
    List(JobsListArgs),
    /// Cancel an active transfer on a remote daemon
    Cancel(JobsCancelArgs),
    /// Watch an active transfer until it completes
    Watch(JobsWatchArgs),
    /// Show a job's log — every file copied, deleted and failed, with phase
    /// times — from this machine, a log file, or a daemon
    Log(JobsLogArgs),
    /// Keep a job run on this machine as a saved job
    Save(JobsSaveArgs),
    /// Write a job run on this machine, or a saved job, to a file
    Export(JobsExportArgs),
    /// Run a saved job, or a job file, again
    Run(JobsRunArgs),
    /// Delete a saved job
    Delete(JobsDeleteArgs),
}

#[derive(Args, Clone, Debug)]
pub struct JobsSaveArgs {
    /// A job run on this machine, as `blit jobs list` shows it
    pub job_id: String,
    /// The name to keep it under
    #[arg(value_parser = parse_job_name)]
    pub name: String,
}

#[derive(Args, Clone, Debug)]
pub struct JobsExportArgs {
    /// A job run on this machine, or a saved job's name
    #[arg(value_name = "JOB|NAME")]
    pub job: String,
    /// The file to write it to
    pub file: PathBuf,
}

#[derive(Args, Clone, Debug)]
pub struct JobsRunArgs {
    /// A saved job's name, or a job file given as a path (`./job.json`;
    /// written by `--export` or `blit jobs export`)
    #[arg(value_name = "NAME|FILE")]
    pub job: String,
}

#[derive(Args, Clone, Debug)]
pub struct JobsDeleteArgs {
    /// The saved job to delete
    pub name: String,
}

/// A saved job's name, checked as the command line reads it.
fn parse_job_name(name: &str) -> Result<String, String> {
    if blit_core::job_record::valid_job_name(name) {
        Ok(name.to_string())
    } else {
        Err("a job name is 1 to 64 letters, digits, `-`, `_` or `.`, not starting with `.`".into())
    }
}

